pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: remaining space after placement
    let mut score = post_residual as f64;

    // Progress through the stream (0.0 .. 1.0)
    let progress = step_index as f64 / total_items as f64;

    // Aggressive 2‑step lookahead: reward bins that can also fit the next item
    if next_item_size > 0 {
        let diff = post_residual as i32 - next_item_size as i32;
        if diff >= 0 {
            // Can fit the next item as well – strongly reward
            score -= 2.0 * diff as f64;
        } else {
            // Cannot fit the next item – mild penalty
            score += 1.5 * (-diff) as f64;
        }
    }

    // Prefer bins whose residual is close to the mean residual
    let mean_diff = post_residual as f64 - mean_residual;
    score += (mean_diff * mean_diff) * 0.01;

    // If this is a brand‑new empty bin, consider opening it only when many open bins exist
    if bin_residual == bin_capacity {
        // Larger number of open bins → slightly lower score for opening a new bin
        let open_penalty = (open_bins_count as f64).sqrt();
        score -= open_penalty * 5.0;
    }

    // If this is the sole bin that can accommodate the item, strongly reward using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Near the end of the stream, favor tighter packing
    if progress > 0.8 {
        score -= 0.1 * (bin_capacity - post_residual) as f64;
    }

    // Final score: lower is better
    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    let p = step_index as f64 / total_items as f64;
    let residual_f64 = post_residual as f64;
    let capacity_f64 = bin_capacity as f64;
    let one = capacity_f64 / capacity_f64; // equals 1.0

    let residual_sq = residual_f64 * residual_f64;
    let penalty = residual_sq * (one - p) / capacity_f64;

    let mean_diff = (mean_residual - residual_f64) * (next_item_size as f64) / capacity_f64;

    let bin_util = (capacity_f64 - residual_f64) / capacity_f64;

    let open_diff = (open_bins_count as f64 - fitting_bins_count as f64) * (one - bin_util);

    let score = residual_f64 - penalty - mean_diff - open_diff;
    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual left after placing the item
    let mut score = post_residual as f64;

    // 1. Strict dead‑space avoidance
    //   If the remaining gap is smaller than the next item, it will likely be unusable.
    //   Add a heavy penalty to discourage such fits.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 1_000.0;
    }

    //   Small gaps (≤ 10) are also considered dead space.
    //   Penalize them proportionally to how far below the threshold they are.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 5.0;
    }

    // 2. Open‑bin pressure
    //   The more bins we keep open, the more we should avoid creating new ones.
    //   Add a linear penalty per open bin.
    score += open_bins_count as f64 * 2.0;

    // 3. Fitting‑bin pressure
    //   If only one bin can accept the item, we must use it.
    //   Subtract a large constant to make it the top choice.
    if fitting_bins_count == 1 {
        score -= 500.0;
    }

    // 4. New‑bin candidate handling
    //   A brand‑new empty bin has the maximum residual.
    //   Penalize it unless there are no other viable bins.
    if bin_residual == bin_capacity {
        score += 200.0;
    }

    // 5. Perfect fit bonus
    //   If the item exactly fills the bin, it is an ideal placement.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Normalized stream progress
    let progress = step_index as f64 / total_items as f64;

    // Ratios relative to bin capacity
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    let item_ratio = item_size as f64 / bin_capacity as f64;
    let bin_residual_ratio = bin_residual as f64 / bin_capacity as f64;

    // Start with the raw post‑residual
    let mut score = post_residual as f64;

    // Polynomial coupling of post_residual with progress
    score += (1.0 - progress) * residual_ratio.powi(2) * bin_capacity as f64;

    // Smooth term involving the item size ratio
    score += (1.0 - item_ratio) * residual_ratio * 10.0;

    // Additional penalty for the remaining residual in the bin itself
    score += bin_residual_ratio.powi(2) * 2.0;

    // Penalize if the next item will not fit in the bin after this placement
    if next_item_size > 0 {
        let diff = (next_item_size as i32 - post_residual as i32) as f64;
        if diff > 0.0 {
            score += diff.powi(2) * 0.5;
        }
    }

    // Slightly encourage using bins when few are open
    score += open_bins_count as f64 * 0.05;

    // Penalize deviation from the mean residual across all open bins
    let mean_diff = (mean_residual - post_residual as f64).abs();
    score += mean_diff * 0.1;

    // Strongly favor bins that are the last chance to place this item
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    score
}

