pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score is the residual space left after placing the item.
    let mut score = post_residual as f64;

    // ---------- Aggressive 2‑step lookahead ----------
    if next_item_size > 0 {
        // Difference between the residual after this placement and the size of the next item.
        let diff = (post_residual as i32 - next_item_size as i32).abs() as f64;

        // Exact match gives a large bonus.
        score -= 50.0 / (diff + 1.0);

        // If the residual is too small to hold the next item, add a penalty proportional to the missing space.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64;
        } else {
            // If extra space remains but the next item still fits, slightly reward small residual difference.
            score -= diff * 0.1;
        }
    }

    // ---------- Mean residual balancing ----------
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += mean_diff * 0.05;

    // ---------- Very small residual penalty ----------
    if post_residual < 5 {
        score += 20.0;
    }

    // ---------- Single‑fitting‑bin preference ----------
    if fitting_bins_count == 1 && bin_residual > 0 {
        // Encourage using the only fitting bin unless it creates a huge waste.
        let residual_ratio = post_residual as f64 / bin_capacity as f64;
        score -= residual_ratio * 10.0;
    }

    // ---------- New‑bin handling ----------
    if bin_residual == bin_capacity {
        // If there are already open bins, penalize opening a new one unless the waste is small.
        if open_bins_count > 0 {
            let waste = (bin_capacity - item_size) as f64;
            if waste > mean_residual {
                score += (waste - mean_residual) * 0.2;
            }
        }
    }

    // ---------- Progress‑based bias ----------
    let progress = step_index as f64 / total_items as f64;
    score += progress * 0.05;

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Base score: the residual left in the bin after placement
    let mut score = post_residual as f64;

    // Reward packing large items: subtract a fraction of the item size
    score -= (item_size as f64) * 0.30;

    // Strict dead‑space avoidance:
    // If the remaining space is too small to fit the next item and this is not the only fitting bin,
    // add a penalty proportional to the gap that would be unusable.
    if next_item_size > 0
        && post_residual < next_item_size
        && fitting_bins_count > 1
    {
        score += (next_item_size - post_residual) as f64 * 5.0;
    }

    // Penalize leaving more residual than the current average residual
    if post_residual > mean_residual as u32 {
        score += (post_residual - mean_residual as u32) as f64 * 0.20;
    }

    // Open‑bins pressure: discourage keeping many bins open
    score += (open_bins_count as f64) * 1.50;

    // New‑bin penalty when there are already open bins (encourage reuse)
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 30.0;
    }

    // Optional: adapt penalty as the stream progresses
    // (later in the stream we are more willing to open new bins)
    let progress = step_index as f64 / total_items as f64;
    score += progress * 2.0;

    score
}
